style.css:
@-moz-document url-prefix("https://studio.penguinmod.com/") {
:root {
  --ut-black: #000;
  --ut-dark: #111;
  --ut-gray: #222;
  --ut-border: #555;
  --ut-white: #fff;
  --ut-yellow: #ffff00;
  --ut-red: #ff0000;
}

/* EVERYTHING */
html,
body {
  background: #000 !important;
  color: #fff !important;
}

/* MAIN EDITOR */
[class*="editor"],
[class*="workspace"],
[class*="layout"],
[class*="sidebar"],
[class*="panel"],
[class*="stage"] {
  background-color: #000 !important;
  color: #fff !important;
}

/* HEADER */
[class*="menu-bar"],
[class*="menuBar"],
header {
  background: #000 !important;
  border-bottom: 2px solid #fff !important;
}

/* TABS */
[class*="tab"] {
  background: #111 !important;
  color: #fff !important;
  border: 2px solid #555 !important;
  border-radius: 0 !important;
}

[class*="tab"][class*="active"],
[class*="tab"]:hover {
  background: #000 !important;
  color: #ffff00 !important;
  border-color: #ffff00 !important;
}

/* BUTTONS */
button {
  background: #111 !important;
  color: #fff !important;
  border: 2px solid #555 !important;
  border-radius: 0 !important;
  box-shadow: 3px 3px #000 !important;
}

button:hover {
  background: #222 !important;
  color: #ffff00 !important;
  border-color: #ffff00 !important;
}

/* INPUTS */
input,
textarea,
select {
  background: #000 !important;
  color: #fff !important;
  border: 2px solid #777 !important;
  border-radius: 0 !important;
}

/* CATEGORY LIST */
[class*="category"] {
  background: #000 !important;
  color: #fff !important;
  border-radius: 0 !important;
}

[class*="category"]:hover {
  background: #222 !important;
  color: #ffff00 !important;
}

/* BLOCK PALETTE */
[class*="blocks"],
[class*="block-palette"],
[class*="flyout"] {
  background: #111 !important;
  border-color: #555 !important;
}

/* SCRIPT AREA */
[class*="blocklyWorkspace"],
[class*="blocklyMainBackground"] {
  background-color: #000 !important;
}

/* SCRIPT GRID */
[class*="blocklyGridPattern"] {
  opacity: .15 !important;
}

/* DROPDOWNS */
[class*="dropdown"],
[class*="menu"] {
  background: #111 !important;
  color: #fff !important;
  border: 2px solid #fff !important;
  border-radius: 0 !important;
}

/* STAGE */
[class*="stage-wrapper"],
[class*="stage-header"],
[class*="stage-controls"] {
  background: #000 !important;
  border-color: #fff !important;
}

/* TEXT */
body,
span,
label,
p,
div {
  text-shadow: none !important;
}

/* YELLOW UNDERTALE-STYLE HIGHLIGHTS */
[class*="selected"],
[class*="active"] {
  outline-color: #ffff00 !important;
}

/* REMOVE MODERN ROUNDED UI */
* {
  border-radius: 0 !important;
}

/* SCROLLBARS */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: #000;
}

::-webkit-scrollbar-thumb {
  background: #555;
  border: 2px solid #000;
}

::-webkit-scrollbar-thumb:hover {
  background: #fff;
}

/* ================================================= */
/* RED SOUL GREEN FLAG                               */
/* ================================================= */

img[src*="green"],
img[alt*="Go"],
img[alt*="go"],
[class*="green-flag"] img,
[class*="greenFlag"] img,
[class*="green-flag"] {
  content: url("data:image/webp;base64,REPLACE_WITH_SOUL_DATA");
}

/* MAKE IT LOOK LIKE THE UNDERTALE SOUL */
[class*="green-flag"],
[class*="greenFlag"] {
  background: #000 !important;
  border: 2px solid #555 !important;
  border-radius: 0 !important;
}
}
